data.action:
function saveItems(s, player){
	if((s.info.xml.get("type") != "storehouse" && s.info.xml.get("saveItems") != "true") || s.area == null || s.inventory == null) return;
	if(s.area.id == "science1" && s.area.getStructureById('crashed_ship.crack1') != null){
		var n = player.areas.get("crashed_ship.cave1").getMainStorehouse();
		if(n != null) n.accessInventory().addAll(s.inventory);
	} else if(s.area.id == "start"){
		var n = player.areas.get("alchemist.portal").getMainStorehouse();
		if(n != null) n.accessInventory().addAll(s.inventory);
	}
}

addedToArea.action:
count = 0.0; function scorchTile(x, y, layer, append){
	var t = area.getTile(x, y, layer); if(t != null && Tile.exists(t.id+append))
		area.setTile(x, y, layer, area.addTileIndex(t.id+append));
} function damageTile(x, y){
	area.breakBrick(x, y, 4, 12, true, this); setOre(x, y, null);
	scorchTile(x, y+1, BACK_LAYER, ".scorched"); scorchTile(x, y+1, BASE_LAYER, ".scorched");
	return false;
}

object.onFrame:
count += frames; if(count >= 8){
			count -= 8; for(o in this.getOverlappingObjects(null, damageTile)){
				if(o.info.xml.get("canBombard") == "false"){}
				else if(o.info.xml.nodeName() == "npc") area.removeObject(o); 
				else if(o.attackPower(1, 1, 0, null, false) > 0 && o.getDefense(false, false, false) < 20) o.damage(50, FLAG_IGNORE_DEFENSE|FLAG_HIDE_ATTACKER, o);
				else {var l = o.getLayer(); if(l == BUSH_LAYER || l == ITEM_LAYER || l == TRAP_LAYER) area.removeObject(o);}
			} for(y in Math.floor(this.yTop()/Tile.SIZE)...(this.tile_y+2)){
				scorchTile(this.tile_x-1, y, BACK_LAYER, ".scorchedt"); scorchTile(this.tile_x-1, y, BASE_LAYER, ".scorchedt");
				scorchTile(this.tile_right, y, BACK_LAYER, ".scorchedt"); scorchTile(this.tile_right, y, BASE_LAYER, ".scorchedt");
			} for(s in this.getOverlappingStructure(null, null, 0)){
				var d = s.info.xml.get("id")+".destroyed";
				if(s.info.xml.get("destroyRemove") == "true"){saveItems(s, player); area.removeStructure(s, null);}
				else if(StructureInfo.exists(d)){saveItems(s, player); area.removeStructure(s,null); getStructure(d).build(null, area, s.xPos, s.yPos);}
			}
		}

data.action:
function closeMarkets(start, science1){
	var a = start; var s = a.getStructureById("food_market"); if(s != null){a.removeStructure(s,null); getStructure("food_market.closed").build(null, a, s.xPos, s.yPos);}
	var s = a.getStructureById("weaps_market"); if(s != null){a.removeStructure(s,null); getStructure("weaps_market.closed").build(null, a, s.xPos, s.yPos);}
	var s = a.getStructureById("mineral_market"); if(s != null){a.removeStructure(s,null); getStructure("mineral_market.closed").build(null, a, s.xPos, s.yPos);}
	a = science1; var s = a.getStructureById("sci1.food_market"); if(s != null){a.removeStructure(s,null); getStructure("sci1.food_market.closed").build(null, a, s.xPos, s.yPos);}
	var s = a.getStructureById("sci1.weaps_market"); if(s != null){a.removeStructure(s,null); getStructure("sci1.weaps_market.closed").build(null, a, s.xPos, s.yPos);}
	var s = a.getStructureById("sci1.mineral_market"); if(s != null){a.removeStructure(s,null); getStructure("sci1.mineral_market.closed").build(null, a, s.xPos, s.yPos);}
}

